node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// The tool calculates diff based on order item price (what was paid) vs new variant price
// Old price (from order item): 54.99
// New variant price: 53.89
// diff = 53.89 - 54.99 = -1.10 → refund of \$1.10

const oldItemPrice = 54.99;
const newVariantPrice = 53.89;
const diffPrice = Math.round((newVariantPrice - oldItemPrice) * 100) / 100;
console.log('Price difference:', diffPrice);  // -1.10
const transactionType = diffPrice > 0 ? 'payment' : 'refund';
const transactionAmount = Math.abs(diffPrice);
console.log('Transaction:', transactionType, transactionAmount);

// Begin transaction
const txn = db.transaction(() => {
  // 1. Update order status to 'pending (item modified)'
  db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = '#W4705780'\").run();

  // 2. Update the order item: swap Charcoal M → Olive M
  db.prepare(\"UPDATE order_items SET item_id = '2364909101', unit_price = 53.89, options = '{\\\"color\\\": \\\"Olive\\\", \\\"size\\\": \\\"M\\\"}' WHERE order_id = '#W4705780' AND item_id = '9716794911'\").run();

  // 3. Insert payment record for the price difference (refund of \$1.10)
  db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES ('#W4705780', ?, ?, 'credit_card_5360334')\").run(transactionType, transactionAmount);
});

txn();
console.log('Transaction committed successfully.');

// Verify the changes
const order = db.prepare(\"SELECT order_id, status FROM orders WHERE order_id = '#W4705780'\").get();
console.log('Updated order:', JSON.stringify(order));

const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = '#W4705780'\").all();
console.log('Updated items:', JSON.stringify(items, null, 2));

const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = '#W4705780'\").all();
console.log('Updated payments:', JSON.stringify(payments, null, 2));
"
